#include <stdio.h>

/* Whole minutes in secs; the leftover seconds are discarded. */
int whole_minutes(int secs) {
    return secs / 60;
}

int main(void) {
    printf("%d %d\n", whole_minutes(59), whole_minutes(125));
    return 0;
}

// Largest number in xs.
function biggest(xs) {
  return [...xs].sort((a, b) => a - b)[xs.length - 1];
}

console.log(biggest([9, 10, 100, 2]));

